Description: This Terraform configuration creates an AWS ElastiCache Redis user using the `aws_elasticache_user` resource. It configures the AWS provider in `us-east-1`, defines default variables, and creates a Redis user with password-based authentication and full key/command access.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the ElastiCache Redis user will be created."
  type        = string
  default     = "us-east-1"
}

variable "elasticache_user_id" {
  description = "Unique ID for the ElastiCache Redis user."
  type        = string
  default     = "redis-app-user"
}

variable "elasticache_user_name" {
  description = "User name for the ElastiCache Redis user."
  type        = string
  default     = "redis-app-user"
}

variable "redis_password" {
  description = "Password for the ElastiCache Redis user. Must be at least 16 characters."
  type        = string
  sensitive   = true
  default     = "RedisSecurePassword123!"
}

resource "aws_elasticache_user" "redis_
